# ───────────────────────── 6 ─────────────────────────
CHAPTERS.append({
    "title": "تشكيل التكتلات: الدعوات",
    "intro": "لا انتخاب: من يحمل صفة «رئيس تكتل» (أساسيةً ثبّتته فيها الإدارة، أو موسميةً منحته إياها لهذا الموسم) يقدّم طلب تشكيل التكتل في مواعيد الاستقبال، ويدعو إليه المجموعات وكادره دعوةً دعوة (الفصل 8). وكل مدعو يقبل أو يعتذر من حسابه في «تشكيل التكتلات» ← «دعواتي»: رئيس المجموعة يقبل دعوة واحدة لمجموعته فتدخل التكتل بحجاجها، والموجّه والمعاون يُدعيان إلى مقعد في مجموعة، والمنسق والموجّهة ومعاون التكتل إلى التكتل كله. لكل شخص مكان واحد في الموسم.",
    "sections": [
        {"title": "دعواتي", "steps": [
            S("دعوة إلى مقعد", "في «دعواتي» بطاقة لكل دعوة: التكتل ورئيسه، وما يدعوك إليه (مثل «موجّه ديني في مجموعة البشرى»)، وزرا «أقبل» و«أعتذر». تُجاب الدعوات في مدة تشكيل التكتلات.", "inv-seat",
              do=["اضغط «أقبل» (الإطار 1) أو «أعتذر» (الإطار 2)."], r="يصل ردك إلى رئيس التكتل فوراً."),
            S("قبلت الدعوة", "تصير في مكانك في التكتل، وتُعتذر عنك تلقائياً دعواتك الأخرى إلى مكان آخر. ويظهر مكانك في «ملفي» وفي إدارة مجموعتك أو مجموعات التكتل.", "inv-accepted",
              do=["—"], r="—"),
            S("دعوة مجموعتك", "رئيس المجموعة تصله دعوة تكتل لمجموعته بحجاجها: يقبل واحدة فقط، فتدخل مجموعته التكتل بفئتها ومقاعدها.", "cluster-member",
              do=["اقبل دعوة التكتل الذي تختاره لمجموعتك."], r="تدخل مجموعتك التكتل، ويملأ رئيسه مقاعد فريقها."),
            S("دعوة نائباً لرئيس التكتل", "رئيس مجموعة في التكتل قد يدعوه رئيسه نائباً له، ومن كادر التكتل من يُدعى محاسباً له: صفتان ثانويتان فوق مكانه، تقبلهما من «دعواتي» كذلك.", "inv-deputy",
              do=["اقبل الدعوة أو اعتذر عنها."], r="—"),
        ]},
    ],
})

# ───────────────────────── 7 ─────────────────────────
